CREATE TABLE IF NOT EXISTS gis_controlled_imports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_name text NOT NULL, source_url text, filename text NOT NULL, content_type text, byte_size bigint NOT NULL, sha256 text NOT NULL, artifact_url text NOT NULL, status text NOT NULL DEFAULT 'IMPORTED_UNVERIFIED', provenance_status text NOT NULL DEFAULT 'UNVERIFIED', imported_by text, notes text, created_at timestamptz NOT NULL DEFAULT now());